arguments.command:
d=$(mktemp -d) && cd "$d" && cp "$OLDPWD/cli.py" . && cat > notes.py <<'EOF'
import json, os
def _p(path): return path or "notes.json"
def _load(path):
    p=_p(path)
    if not os.path.exists(p): return []
    try:
        with open(p, encoding="utf-8") as f: data=json.load(f)
    except Exception as e: raise ValueError(f"cannot read {p}: {e}")
    if not isinstance(data, list): raise ValueError(f"{p} is not a list of notes")
    return data
def _save(path, items):
    with open(_p(path), "w", encoding="utf-8") as f: json.dump(items, f, ensure_ascii=False, indent=2)
def add(text, path=None):
    t=text.strip()
    if not t: raise ValueError("note text must not be empty")
    items=_load(path); items.append(t); _save(path, items); return len(items)
def list(path=None): return _load(path)
def delete(number, path=None):
    items=_load(path)
    if not items: raise ValueError("no notes to delete")
    if number < 1 or number > len(items): raise ValueError(f"note {number} does not exist")
    return items.pop(number-1) if not _save(path, items) else None
EOF
sed -i '' 's/return items.pop(number-1) if not _save(path, items) else None/rem=items.pop(number-1); _save(path, items); return rem/' notes.py
echo "=== --help ==="; python3 cli.py --help; echo "exit=$?"
